vars.crud_derived_hooks:
protected override Expression<Func<EntityName, EntityNameListItem>> Projection =>
    e => new EntityNameListItem(e.Id, e.Name, e.RelatedEntity!.Name);

protected override EntityName ToEntity(CreateEntityNameRequest input) =>
    new() { Name = input.Name, RelatedEntityId = input.RelatedEntityId };

protected override void Apply(UpdateEntityNameRequest input, EntityName entity)
{
    entity.Name = input.Name;
    entity.RelatedEntityId = input.RelatedEntityId;
}

vars.crud_abstract_hooks:
/// The listing projection. Runs in SQL, so it may only contain what EF Core
/// can translate — no method calls on the entity.
protected abstract Expression<Func<TEntity, TListItem>> Projection { get; }

protected abstract TEntity ToEntity(TCreateRequest input);

protected abstract void Apply(TUpdateRequest input, TEntity entity);
